(()=>{
const q=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)];
const style=document.createElement('style');style.textContent='.ubo-grid{align-items:start}.ubo-grid>.field>span:first-child{display:block;min-height:23px;margin-bottom:7px}.ubo-grid .nationality-picker details{padding:11px 12px;min-height:46px}.ubo-grid .selected-countries{display:none}';document.head.append(style);
// Retain old controls for draft migration, but remove them from the active form.
['finance-revenue-status','finance-report-currency','finance-revenue','finance-period-start','finance-period-end','finance-results','finance-audited','finance-audit-start','finance-audit-end','finance-audit-latest','finance-audit-newer-period','finance-report-code'].forEach(id=>{const e=q('#'+id);if(e){e.required=false;e.closest('label').hidden=true;}});
q('#finance-term').closest('label').querySelector('span').textContent='Over how many years would you prefer to repay the financing? (optional)';q('#finance-term').placeholder='e.g. 5 years';
const year=document.createElement('label');year.className='field';year.innerHTML='<span>Latest annual audited financial statements — financial year ending</span><select id="finance-audit-year" required><option value="">Select year</option>'+Array.from({length:8},(_,i)=>'<option>'+(2026-i)+'</option>').join('')+'<option>Earlier year</option><option>No audited statements available yet</option></select><span class="hint">Choose the year of your latest completed audit.</span>';q('[data-screen="13"] .panel:last-of-type').append(year);
const industries=q('#industry');for(const o of [...industries.options]){if(o.textContent==='Online gaming & gambling'){o.textContent='Gambling & betting — real-money wagering';o.value=o.textContent;}if(o.textContent==='Forex & CFD services'){o.textContent='Forex brokerage & CFD dealing';o.value=o.textContent;}if(o.textContent==='Crypto & digital assets'){o.textContent='Crypto-asset services — exchange, custody or brokerage';o.value=o.textContent;}}
industries.add(new Option('Adult industry'));
industries.add(new Option('Video games & esports — no gambling or wagering'));industries.add(new Option('Blockchain / crypto software development — no customer asset services'));
const regulated=['Gambling & betting — real-money wagering','Forex brokerage & CFD dealing','Crypto-asset services — exchange, custody or brokerage'];
function licence(){const forced=regulated.includes(industries.value),yes=q('[name="licence"][value="yes"]').checked,no=q('[name="licence"][value="no"]').checked;q('[name="licence"][value="no"]').disabled=false;q('#licences').hidden=!yes;all('#licences input').forEach(e=>e.required=yes);const reason=q('#licence-applicability');if(reason){reason.hidden=!(forced&&no);q('#licence-applicability-reason').required=forced&&no;}}
const permissionReason=document.createElement('label');permissionReason.className='field';permissionReason.id='licence-applicability';permissionReason.hidden=true;permissionReason.innerHTML='<span>Explain why this activity does not require a licence or authorisation in the relevant jurisdiction</span><textarea id="licence-applicability-reason" placeholder="State the actual activity, jurisdiction and the basis for this answer. Applicability remains subject to verification."></textarea>';q('#licences').after(permissionReason);industries.addEventListener('change',licence);all('[name="licence"]').forEach(e=>e.addEventListener('change',licence));q('#add-licence').addEventListener('click',()=>setTimeout(licence,0));
const hint=document.createElement('p');hint.className='hint';hint.textContent='For regulated services, provide the applicable licence or authorisation reference. Jurisdiction and scope will be verified; this field does not establish validity.';q('#licences').append(hint);
const plc=document.createElement('section');plc.className='panel';plc.hidden=true;plc.innerHTML='<h2>PLC listing status</h2><label class="field"><span>Is the company listed on a stock exchange?</span><select id="plc-listed"><option value="">Select…</option><option>Yes</option><option>No</option></select></label><div id="plc-listing" hidden><label class="field"><span>Stock exchange and ticker / listing identifier</span><input id="plc-exchange"></label><label class="field"><span>Public ownership disclosure or issuer-page URL</span><input id="plc-disclosure" type="url"></label><p class="hint">SOPHIMA must verify the listing and applicable disclosure requirements before relying on this route.</p></div>';q('[data-screen="4"]').prepend(plc);
const uboSection=q('#ubos').closest('section');
function plcUI(){const is=q('#entity-type').value.startsWith('Public limited');plc.hidden=!is;q('#plc-listing').hidden=!is||q('#plc-listed').value!=='Yes';uboSection.hidden=false;all('[data-screen="4"] label.field').filter(l=>l.textContent.includes('offer a personal account to a UBO')).forEach(l=>l.hidden=q('#account-type').value==='financing');}
q('#plc-listed').onchange=plcUI;
const prevRefresh=refreshFlow;refreshFlow=function(){prevRefresh();plcUI();};window.refreshFlow=refreshFlow;
const prevOwnership=ownershipReady;ownershipReady=function(){if(q('#entity-type').value.startsWith('Public limited')){if(!q('#plc-listed').value){note('Please indicate whether the PLC is stock-exchange listed.');return false;}if(q('#plc-listed').value==='Yes'){if(!q('#plc-exchange').value.trim()||!q('#plc-disclosure').value.trim()||!q('#plc-disclosure').checkValidity()){note('Please provide the stock exchange, listing identifier and valid public disclosure URL.');return false;}}}return prevOwnership();};
const prevShow=showPage;showPage=function(n){if(currentPage===2&&activeFlow().indexOf(n)>activeFlow().indexOf(2)){licence();if(q('[name="licence"][value="yes"]').checked&&all('#licences input').some(e=>!e.value.trim())){note('Please enter the licence number and issuing authority for each licence you added.');return;}}prevShow(n);};
const prevReview=review;review=function(){prevReview();if(q('#entity-type').value.startsWith('Public limited')&&q('#plc-listed').value==='Yes'){const term=all('#review-summary dt').find(t=>t.textContent.startsWith('Ownership'));if(term)term.nextElementSibling.textContent='Listed PLC — public disclosure supplied, verification pending';}};
// Country screening is integrated at the platform boundary; no stale local list implies clearance.
licence();plcUI();
})();
